import_type:
with fname AS (select 
	coalesce(source||'.','')|| name as full_name 
from imports)

select 
	case 
		when instr(full_name,'.') = 0 then full_name 
		else substr(full_name,1,instr(full_name,'.')-1)
	end as fname,
	count(*) as count 
from fname
group by fname
order by count desc 
limit 40;
